static int hextoint(int c) { /* <=== hextoint */ 
	if (!isascii ((ut8) c))
		return -1;
	if (isdigit ((ut8) c))
		return c - '0';
	if ((c >= 'a') && (c <= 'f'))
		return c + 10 - 'a';
	if (( c>= 'A') && (c <= 'F'))
		return c + 10 - 'A';
	return -1;
}

static inline int nextcas(void) { /* <=== nextcas */ 
	static ut32 cas = 1;
	if (!cas) {
		cas++;
	}
	return cas++;
}

