SDB_API SdbKv* sdb_kv_new2(const char *k, int kl, const char *v, int vl) { /* <=== sdb_kv_new2 */ 
	SdbKv *kv;
	if (v) {
		if (vl >= SDB_VSZ) {
			return NULL;
		}
	} else {
		vl = 0;
	}
	if (kl >= SDB_KSZ) {
		return NULL;
	}
	kv = R_NEW0 (SdbKv);
	kv->key_len = kl;
	kv->key = malloc (kv->key_len + 1);
	if (!kv->key) {
		free (kv);
		return NULL;
	}
	memcpy (kv->key, k, kv->key_len + 1);
	kv->value_len = vl;
	if (vl) {
		kv->value = malloc (vl + 1);
		if (!kv->value) {
			free (kv->key);
			free (kv);
			return NULL;
		}
		memcpy (kv->value, v, vl + 1);
	} else {
		kv->value = NULL;
		kv->value_len = 0;
	}
	kv->cas = nextcas ();
	kv->expire = 0LL;
	return kv;
}

static ut32 sdb_set_internal(Sdb* s, const char *key, char *val, int owned, ut32 cas) { /* <=== sdb_set_internal */ 
	ut32 vlen, klen;
	SdbKv *kv;
	bool found;
	if (!s || !key) {
		return 0;
	}
	if (!val) {
		val = "";
	}
	// XXX strlen computed twice.. because of check_*()
	klen = strlen (key);
	vlen = strlen (val);
	if (klen >= SDB_KSZ || vlen >= SDB_VSZ) {
		return 0;
	}
	if (s->journal != -1) {
		sdb_journal_log (s, key, val);
	}
	cdb_findstart (&s->db);
	kv = sdb_ht_find_kvp (s->ht, key, &found);
	if (found && kv->value) {
		if (cdb_findnext (&s->db, sdb_hash (key), key, klen)) {
			if (cas && kv->cas != cas) {
				return 0;
			}
			if (vlen == kv->value_len && !strcmp (kv->value, val)) {
				sdb_hook_call (s, key, val);
				return kv->cas;
			}
			kv->cas = cas = nextcas ();
			if (owned) {
				kv->value_len = vlen;
				free (kv->value);
				kv->value = val; // owned
			} else {
				if ((ut32)vlen > kv->value_len) {
					free (kv->value);
					kv->value = malloc (vlen + 1);
				}
				memcpy (kv->value, val, vlen + 1);
				kv->value_len = vlen;
			}
		} else {
			sdb_ht_delete (s->ht, key);
		}
		sdb_hook_call (s, key, val);
		return cas;
	}
	// empty values are also stored
	// TODO store only the ones that are in the CDB
	if (owned) {
		kv = sdb_kv_new2 (key, klen, NULL, 0);
		if (kv) {
			kv->value = val;
			kv->value_len = vlen;
		}
	} else {
		kv = sdb_kv_new2 (key, klen, val, vlen);
	}
	if (kv) {
		ut32 cas = kv->cas = nextcas ();
		sdb_ht_insert_kvp (s->ht, kv, true /*update*/);
		sdb_hook_call (s, key, val);
		return cas;
	}
// kv set failed, no need to callback	sdb_hook_call (s, key, val);
	return 0;
}

R_API char *r_str_trim_tail(char *str) { /* <=== r_str_trim_tail */ 
	int length;

	if (!str) {
		return NULL;
	}
	length = strlen (str);
	if (!length) {
		return str;
	}

	while (length--) {
		if (ISWHITECHAR (str[length])) {
			str[length] = '\0';
		} else {
			break;
		}
	}

	return str;
}

